<?php $rows = supplier_rows(); ?>
<section class="page-head"><h2>الموردين</h2><p>بيانات المورد، نوع المنتجات، وفاتورة واردة مع الرصيد المتبقي.</p></section>
<form class="panel grid-form" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>اسم المورد<input name="name" required></label><label>الهاتف<input name="phone"></label><label>نوع المنتجات<input name="product_type"></label><label>رقم فاتورة واردة<input name="invoice_number"></label><label>قيمة الفاتورة<input name="invoice_total" type="number" step="1" min="0" placeholder="0"></label><label>المدفوع<input name="invoice_paid" type="number" step="1" min="0" placeholder="0"></label><label>تاريخ الفاتورة<input name="invoice_date" type="date" value="<?= e(date('Y-m-d')) ?>"></label><label>ملاحظات<input name="notes"></label><button class="btn primary">حفظ المورد</button></form>
<div class="panel"><table><thead><tr><th>المورد</th><th>الهاتف</th><th>نوع المنتجات</th><th>إجمالي الفواتير</th><th>الرصيد المتبقي</th></tr></thead><tbody><?php foreach ($rows as $s): ?><tr><td><?= e($s['name']) ?></td><td><?= e($s['phone']) ?></td><td><?= e($s['product_type']) ?></td><td><?= money($s['total_invoices']) ?></td><td><?= money($s['total_due']) ?></td></tr><?php endforeach; ?></tbody></table></div>
